define('ROOTDIR_DNA', plugin_dir_path(__FILE__));

function dja_options_install() {
    set_dja_options_install();
}

// run the install scripts upon plugin activation
register_activation_hook(__FILE__, 'dja_options_install');
add_action('admin_bar_menu', 'donasiaja_add_admin_bar_menu', 100);

function donasiaja_add_admin_bar_menu($admin_bar) {
	global $wpdb;
	$table_name = $wpdb->prefix . "dja_settings";

	$query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="fundraiser_on" ORDER BY id ASC');
    $fundraiser_on 	= $query_settings[0]->data;

    $plugin_license = strtoupper($GLOBALS['donasiaja_vars']['plugin_license']);

	// role
    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];

    if($role=='administrator'){

    	if (!current_user_can('manage_options')) {
	        return;
	    }

	    $admin_bar->add_menu(array(
	        'id'    => 'donasiaja-menu',
	        'title' => 'DonasiAja',
	        'href'  => admin_url('admin.php?page=donasiaja_dashboard'), // ganti dengan slug page kamu
	        'meta'  => array(
	            'title' => __('DonasiAja Dashboard'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting1',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'Dashboard',
	        'href'   => admin_url('admin.php?page=donasiaja_dashboard'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Dashboard'),
	        ),
	    ));
		
	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting2',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'Campaign',
	        'href'   => admin_url('admin.php?page=donasiaja_data_campaign'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Campaign'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting3',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'Analytics',
	        'href'   => admin_url('admin.php?page=donasiaja_data_analytics'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Analytics'),
	        ),
	    ));

	    if($fundraiser_on=='1'){
			if($plugin_license=='ULTIMATE') {
				
			    $admin_bar->add_menu(array(
			        'id'     => 'donasiaja-submenu-setting4',
			        'parent' => 'donasiaja-menu',
			        'title'  => 'Fundraising',
			        'href'   => admin_url('admin.php?page=donasiaja_data_fundraising'), // ganti slug sesuai page setting plugin
			        'meta'   => array(
			            'title' => __('Fundraising'),
			        ),
			    ));
			}
		}

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting5',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'Shortcode',
	        'href'   => admin_url('admin.php?page=donasiaja_data_shortcodes'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Shortcode'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting6',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'Members',
	        'href'   => admin_url('admin.php?page=donasiaja_data_members'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Members'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting7',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'My Donate',
	        'href'   => admin_url('admin.php?page=donasiaja_mydonate'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('My Donate'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting8',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'My Profile',
	        'href'   => admin_url('admin.php?page=donasiaja_myprofile'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('My Profile'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiaja-submenu-setting9',
	        'parent' => 'donasiaja-menu',
	        'title'  => 'Settings',
	        'href'   => admin_url('admin.php?page=donasiaja_settings'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Settings'),
	        ),
	    ));
    }
}



