function dja_options_install_later() {
	global $wpdb;
	$table_name = $wpdb->prefix . "options";
	$table_name2 = $wpdb->prefix . "dja_settings";

	// GET POST
    $id = $_POST['datanya'][0];

    if($id=='donasiaja'){
		dja_options_install();
		dja_options_install_data();
	}

	ob_clean();
	echo 'success';

	wp_die();

}
add_action( 'wp_ajax_dja_options_install_later', 'dja_options_install_later' );
add_action( 'wp_ajax_nopriv_dja_options_install_later', 'dja_options_install_later' );



function deactivate_plugin_dna() {
 	
 	// REMOVE ROLE
    $role = get_role( 'donatur' );
    $role->remove_cap( 'upload_files' );
    $role->remove_cap( 'edit_posts' );
    $role->remove_cap( 'edit_published_posts' );
    $role->remove_cap( 'publish_posts' );
    $role->remove_cap( 'read' );
    $role->remove_cap( 'level_2' );
    $role->remove_cap( 'level_1' );
    $role->remove_cap( 'level_0' );
    $role->remove_cap( 'manage_options' );


 	// REMOVE ROLE
    $role = get_role( 'cs' );
    $role->remove_cap( 'upload_files' );
    $role->remove_cap( 'edit_posts' );
    $role->remove_cap( 'edit_published_posts' );
    $role->remove_cap( 'publish_posts' );
    $role->remove_cap( 'read' );
    $role->remove_cap( 'level_2' );
    $role->remove_cap( 'level_1' );
    $role->remove_cap( 'level_0' );
    $role->remove_cap( 'manage_options' );

}
