function djafunction_blocked_ip(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_blocked_ip";
    $table_name2 = $wpdb->prefix . "dja_donate";
    $table_name3 = $wpdb->prefix . "dja_campaign";

    // FROM INPUT
    $ip_user 	= $_POST['datanya'][0];
    $id 	= $_POST['datanya'][1];

    $id_login = wp_get_current_user()->ID;

    $row = $wpdb->get_results('SELECT a.name, a.whatsapp, b.title from '.$table_name2.' a 
    left JOIN '.$table_name3.' b ON b.campaign_id = a.campaign_id where a.id="'.$id.'" ');

    $name = '';
    $title = '';
    $wa = '';
    if($row!=null){
    	$name = $row[0]->name;
    	$title = $row[0]->title;
    	$title = str_replace("&#39;", "'", $title);
    	$wa = $row[0]->whatsapp;
    }

	// Gunakan prepare agar aman
	$ip_whitelists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name WHERE ip = %s and status = 0 LIMIT 1", $ip_user)
	);

	$ip_exists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name WHERE ip = %s and status = 1 LIMIT 1", $ip_user)
	);

	// Debug (jika perlu)

	if ( $ip_whitelists ) {
	    // data sudah ada
	    ob_clean();
	    echo 'whitelist';
	    wp_die();
	}else{

		if ( $ip_exists ) {
		    // data sudah ada
		    ob_clean();
		    echo 'exist';
		    wp_die();
		}else{
			// insert
			$wpdb->insert(
	            $table_name, //table
	            array(
		            'ip' 	=> $ip_user,
		            'note' 	=> $name.' dengan WA: '.$wa.' di Campaign: '.$title,
		            'status' 		=> 1,
		            'created_by' 	=> $id_login,
		            'created_at' 	=> date("Y-m-d H:i:s")),
	            array('%s', '%s') //data format         
	        );
	        ob_clean();
	        echo '<span style="color:#e1345e;font-weight:bold;">'.$ip_user.'</span> <span style="color:#e1345e;">(Blocked)</span>';
	        wp_die();
		}

	}
	
}
add_action( 'wp_ajax_djafunction_blocked_ip', 'djafunction_blocked_ip' );
add_action( 'wp_ajax_nopriv_djafunction_blocked_ip', 'djafunction_blocked_ip' );


function djafunction_open_ip(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_blocked_ip";

    // FROM INPUT
    $ip_user 	= $_POST['datanya'][0];

	// Gunakan prepare agar aman
	$ip_exists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name WHERE ip = %s and status = 1 LIMIT 1", $ip_user)
	);

	// Debug (jika perlu)
	if ( $ip_exists ) {
	    // data exist lalu delete
	    $wpdb->delete(
	        $table_name,             // nama tabel
	        array( 'ip' => $ip_user ), // kondisi where
	        array( '%s' )              // format data
	    );

	    ob_clean();
	    echo $ip_user;

	}else{
		// not exist
        echo 'not exist';
	}

    wp_die();
}
