function djafunction_get_donasi_confirmation(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";
    $table_name2 = $wpdb->prefix . "dja_donate_trash";

    // FROM INPUT
    $donasi_id 	= $_POST['datanya'][0];

    $row = $wpdb->get_results("SELECT * FROM $table_name where id='$donasi_id' ")[0];
    $row2 = $wpdb->get_results("SELECT * FROM $table_name2 where donate_id='$donasi_id' ")[0];

    if($row!=null){
    	$a = $wpdb->update(
	        $table_name, //table
	        array(
	            'img_confirmation_status' 	=> 1,
	        ),
	        array('id' => $donasi_id), //where
	        array('%s'), //data format
	        array('%s') //where format
	    );

    	$time_upload = date('Y-m-d H:i:s',strtotime('+0 hour',strtotime($row->img_confirmation_date)));
	    $readtime = new humanReadtime();
        $a = $readtime->dja_human_time($time_upload);

	    $datenya = new DateTime($row->img_confirmation_date);
        $date_upload = $datenya->format('d').'&nbsp;'.$datenya->format('M').',&nbsp;'.$datenya->format('Y').'&nbsp;-&nbsp;'.$datenya->format('H').':'.$datenya->format('i').'<br><span style='."'".'font-size:10px;color:#91a2b0;'."'".'>'.$a.'<span>';

	    $data_image =  '
		<p class="title_donasi" style="color:#50608e;"><button data-inv="'.$row->invoice_id.'" data-id="'.$donasi_id.'" data-img="'.$row->img_confirmation_url.'" type="button" class="swal2-close del_conf" style="top: auto;right: auto;background: #ea0940;font-size: 20px;border-radius: 4px;margin-left: 175px;margin-top: 25px;position:absolute;width:32px;height:32px;" title="Delete Confirmation"><span class="mdi mdi-trash-can" style="font-size: 15px;"></span></button><img src="'.$row->img_confirmation_url.'" style="width:210px;border-radius:4px;margin-top:20px;margin-bottom:10px;"></p>';

		$data_date = '';
		if($row->img_confirmation_date!=''){
			$data_date = '<p><i>Date upload: '.$date_upload.'</i></p>';
		}

		echo $data_image.$data_date;
    }

    if($row2!=null){

    	$time_upload = date('Y-m-d H:i:s',strtotime('+0 hour',strtotime($row2->img_confirmation_date)));
	    $readtime = new humanReadtime();
        $a = $readtime->dja_human_time($time_upload);

	    $datenya = new DateTime($row2->img_confirmation_date);
        $date_upload = $datenya->format('d').'&nbsp;'.$datenya->format('M').',&nbsp;'.$datenya->format('Y').'&nbsp;-&nbsp;'.$datenya->format('H').':'.$datenya->format('i').'<br><span style='."'".'font-size:10px;color:#91a2b0;'."'".'>'.$a.'<span>';

	    $data_image =  '
		<p class="title_donasi" style="color:#50608e;"><img src="'.$row2->img_confirmation_url.'" style="width:210px;border-radius:4px;margin-top:20px;margin-bottom:10px;"></p>';

		$data_date = '';
		if($row2->img_confirmation_date!=''){
			$data_date = '<p><i>Date upload: '.$date_upload.'</i></p>';
		}

		echo $data_image.$data_date;
    }

	
    wp_die();
}
