function djafunction_get_status() {
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";

    // FROM INPUT
    $d_status 	= $_POST['datanya'][0];
    $d_id 		= $_POST['datanya'][1];

    ob_clean();
    // GET DATA DONATE
    if($d_status=='0'){
    	$row = $wpdb->get_results('SELECT * from '.$table_name.' where id="'.$d_id.'" ')[0];
	    if($row->status=='1'){
	    	ob_clean();
	    	echo 'success';
	    }else{
	    	ob_clean();
	    	echo 'waiting';
	    }
    }else{
    	ob_clean();
    	echo 'waiting';
    }
    
	wp_die();
}
