function djafunction_update_wa(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_blocked_whatsapp";

    // FROM INPUT
    $id 		= $_POST['datanya'][0];
    $whatsapp 	= $_POST['datanya'][1];
    $note 	= str_replace('\\', '', $_POST['datanya'][2]);

    $a = $wpdb->update(
        $table_name, //table
        array(
            'whatsapp' 	=> $whatsapp,
            'note' 	=> $note
        ),
        array('id' => $id), //where
        array('%s'), //data format
        array('%s') //where format
    );
	
	if ($a === false) {
	    // Jika terjadi error
	    $info = 'error';
	} elseif ($a === 0) {
	    // Jika tidak ada baris yang terupdate (misalnya nilai sudah 1 sebelumnya)
	    $info = 'success';
	} else {
	    // Jika berhasil update (1 atau lebih baris diperbarui)
	    $info = 'success';
	}

	ob_clean();
    echo $info;

    wp_die();
}
