			<tr><td>Pesan</td><td>:</td><td><span id="d_comment">'.$comment.'</span></td></tr>
			<tr><td>Donasi</td><td>:</td><td><span id="d_nominal">'.$show_currency.number_format_currency($row->nominal).'</span></td></tr>
