function djafunction_del_donasi(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";
    $table_name2 = $wpdb->prefix . "dja_love";
    $table_name3 = $wpdb->prefix . "dja_donate_trash";
    $table_name4 = $wpdb->prefix . "dja_aff_submit";

    // FROM INPUT
    $donasi_id 	= $_POST['datanya'][0];
    $row = $wpdb->get_results('SELECT * from '.$table_name.' WHERE id="'.$donasi_id.'" ')[0];

    $user_who_del_id = wp_get_current_user()->ID;
    $user_info = get_userdata($user_who_del_id);
    if($user_info!=null){
    	if($user_info->last_name==''){
	    	$user_who_del_name = $user_info->first_name;
	    }else{
	    	$user_who_del_name = $user_info->first_name.' '.$user_info->last_name;
	    }
    }else{
    	$user_who_del_name = 'unidentified';
    }

    // CREATE DONASI
	$wpdb->insert(
        $table_name3, //table
        array(
            'who_del_id' 	 => $user_who_del_id,
            'who_del_name' 	 => $user_who_del_name,
            'donate_id' 	 => $row->id,
            'donate_id' 	 => $row->id,
            'campaign_id' 	 => $row->campaign_id,
            'invoice_id' 	 => $row->invoice_id,
            'user_id' 		 => $row->user_id,
            'name' 			 => $row->name,
            'whatsapp' 		 => $row->whatsapp,
            'email' 		 => $row->email,
            'comment' 		 => $row->comment,
            'anonim' 		 => $row->anonim,
            'payment_method' => $row->payment_method,
            'payment_code'	 => $row->payment_code,
            'payment_number' => $row->payment_number,
            'payment_qrcode' => $row->payment_qrcode,
            'payment_account'=> $row->payment_account,
            'unique_number'  => $row->unique_number,
            'nominal' 		 => $row->nominal,
            'main_donate' 	 => $row->main_donate,
            'info_donate' 	 => $row->info_donate,
            'info_qurban' 	 => $row->info_qurban,
            'info_package2'  => $row->info_package2,
            'info_zfitrah' 	 => $row->info_zfitrah,
            'info_zmaal' 	 => $row->info_zmaal,
            'info_addformula'=> $row->info_addformula,
            'status' 		 => $row->status,
            'cs_id' 		 => $row->cs_id,
            'f0' 			 => $row->f0,
            'f1' 			 => $row->f1,
            'f2' 			 => $row->f2,
            'f3' 			 => $row->f3,
            'f4' 			 => $row->f4,
            'f5' 			 => $row->f5,
            'payment_trx_id' => $row->payment_trx_id,
            'payment_at'	 => $row->payment_at,
            'process_by'	 => $row->process_by,
            'deeplink_url'	 => $row->deeplink_url,
            'payment_gateway'=> $row->payment_gateway,
            'img_confirmation_url'=> $row->img_confirmation_url,
            'img_confirmation_status'=> $row->img_confirmation_status,
            'img_confirmation_date'=> $row->img_confirmation_date,
            'ip'			 => $row->ip,
            'os'			 => $row->os,
            'browser'		 => $row->browser,
            'mobdesktop'	 => $row->mobdesktop,
            'sapaan'	 	 => $row->sapaan,
            'currency'	 	 => $row->currency,
            'created_at' 	 => $row->created_at,
            'deleted_at' 	 => date("Y-m-d H:i:s")),
        array('%s', '%s') //data format
    );

	// on table donasi deleted
    if ( $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM '.$table_name.' WHERE id = %d', $donasi_id ) ) ) {
        $wpdb->query( $wpdb->prepare( 'DELETE FROM '.$table_name.' WHERE id = "'.$donasi_id.'" ' ) );
    }

    // on table dja_aff_submit 
    if ( $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM '.$table_name4.' WHERE donate_id = %d', $donasi_id ) ) ) {
        $wpdb->query( $wpdb->prepare( 'DELETE FROM '.$table_name4.' WHERE donate_id = "'.$donasi_id.'" ' ) );
    }
    ob_clean();
	echo 'success';

    wp_die();
}
