			}
			
		}

		
    	
	}else{

		if($jumlah_donate!=0){

			if($del_campaign_setting!='1'){
				ob_clean();
			    echo 'sudah_ada_donasi';
			}else{
				// ACTION Update TO DB
			    if ( $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM '.$table_name.' WHERE id = %d', $id ) ) ) {
