function donasiaja_schedule_cron_events() {

    global $wpdb;
    $table_name = $wpdb->prefix . "dja_settings";

    // Ambil pengaturan otomatis dan pengaturan follow-up harian dari database
    $query_settings = $wpdb->get_results(
        "SELECT data FROM $table_name WHERE type IN ('automatic_followup_settings', 'daily_followup') ORDER BY id ASC"
    );

    $automatic_followup_settings = $query_settings[0]->data;
    $daily_followup = json_decode($query_settings[1]->data, true);

    // Cek apakah automatic follow-up diaktifkan
    if ($automatic_followup_settings === '1' && !empty($daily_followup)) {

    	$no = 1;
        foreach ($daily_followup as $key => $value) {

            $event_name = 'donasiaja_' . $key . '_event'; // Event name seperti donasiaja_f1_event
            // $time = strtotime('19:57:15');
            $time = strtotime($value[2]);
            $current_time = time();//current_time('timestamp');

            if ($value[0] === 'on') {

            	if ($time <= $current_time) {
	                $time = strtotime('tomorrow', $current_time) + date('H', $time) * 3600 + date('i', $time) * 60;
	            }

                // Jadwalkan cron event harian jika belum terjadwal
                if (!wp_next_scheduled($event_name)) {
                    wp_schedule_event($time, 'daily', $event_name, array($no));
                    error_log("Event terjadwal: $event_name pada " . date('H:i', $time));
                }

            } else {
                // Hapus jadwal cron event jika statusnya off
                $timestamp = wp_next_scheduled($event_name);
                if ($timestamp) {
                    wp_unschedule_event($timestamp, $event_name);
                    error_log("Event dibatalkan: $event_name");
                }
            }
            $no++;
        }
    }
}


// Hook into the 'init' action to schedule our cron event
add_action('wp', 'donasiaja_schedule_cron_events');



function donasiaja_custom_followup_function($data) {

	if (!empty($data)) {

		global $wpdb;
        $table_name = $wpdb->prefix . "dja_custom_followup_scheduler";
        $table_name2 = $wpdb->prefix . "dja_campaign";
 		$table_name3 = $wpdb->prefix . "dja_donate";
 		$table_name4 = $wpdb->prefix . "dja_group_data";
 		$table_name5 = $wpdb->prefix . "dja_settings";

		// check data settingan scheduler
		$query = $wpdb->get_results('SELECT * from '.$table_name.' where code_id="'.$data.'"');

		if($query!=null){
			
			$time 		 	= $query[0]->date_time;
			$followup_number= $query[0]->format; // followup 1 s.d 5, dan 6 = custom
			$message 	 	= $query[0]->custom_format; // custom format message
			$target 	 	= $query[0]->target; // campaign, group, manual
			$group_id 	 	= $query[0]->group_id;
			$campaign_id 	= $query[0]->campaign_id;
			$donatur_status = $query[0]->donatur_status; // all, waiting, success
			$is_first_run 	= $query[0]->is_first_run; // Ambil status eksekusi pertama

			$broadcast_mode = $query[0]->broadcast_mode;
			$batch_size 	= $query[0]->batch_size;
			$send_delay 	= $query[0]->send_delay;

            // Ambil tanggal hari ini
            $current_date = current_time("Y-m-d H:i:s");

            // $info = '';
            // Jika ini pertama kali dijalankan dan start_date sudah lewat, jangan eksekusi WA
            if ($is_first_run == 0 && strtotime($time) < strtotime($current_date)) {

                // Update agar is_first_run menjadi 0 supaya bisa dieksekusi di masa depan
                $a = $wpdb->update(
			        $table_name,
			        array(
			            'is_first_run' 	 => 1
			        ), array('code_id' => $query[0]->code_id), array('%s'), array('%s')
			    );

			    if ($a === false) {
				    // Jika terjadi error
				    // $info = "Gagal update is_first_run untuk code_id: " . $query[0]->code_id;
				} elseif ($a === 0) {
				    // Jika tidak ada baris yang terupdate (misalnya nilai sudah 1 sebelumnya)
				    // $info = "Tidak ada perubahan pada is_first_run untuk code_id: " . $query[0]->code_id;
				} else {
				    // Jika berhasil update (1 atau lebih baris diperbarui)
				    // $info = "Berhasil update is_first_run untuk code_id: " . $query[0]->code_id;
				}

				return false;

            }
			

			if($target=='campaign'){

				// $filter_datestart_now = date("Y-m-d $time");
		        // $filter_datestart_before = date("Y-m-d $time", strtotime($filter_datestart_now. ' - 2 days'));

		        if($donatur_status=='waiting'){
		        	$donatur_status = "AND status='0'";
		        }elseif($donatur_status=='success'){
		        	$donatur_status = "AND status='1'";
		        }else{
		        	$donatur_status = "";
		        }

		        // $query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name3 where campaign_id='$campaign_id' $donatur_status and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");

		       	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name3 where campaign_id='$campaign_id' $donatur_status ");

		        if($query_donate!=null){

		        	$no=1;
		        	foreach($query_donate as $row){

		        		// ambil dari message custom
						if($followup_number=='6'){

						    $data_array = [$row->id, '6', urldecode($message)];
							djafunction_send_wa($data_array);

							// $data_array = ['Cek : '.$row->id, '08123'];
							// djafunction_send_wa2($data_array);

						}else{ // ambil dari message follwup 1 s.d 5

							$data_array = [$row->id, $followup_number, null];
						    djafunction_send_wa($data_array);

						}

						if($broadcast_mode=='in_batch'){
							if ($no % $batch_size == 0) {
								if($send_delay>=1){
									sleep($send_delay);
								}else{
									usleep($send_delay * 1000000);
								}
						    }
						}elseif($broadcast_mode=='one_by_one'){
							if($send_delay>=1){
								sleep($send_delay);
							}else{
								usleep($send_delay * 1000000);
							}
						}else{
							// broadcast all
						}

						

					    $no++;
		        	}
		        }

			}else{

				// $data_array = [842, 1, null];
			    // djafunction_send_wa($data_array);

			    // GROUP

			    $data_by_group = $wpdb->get_results("SELECT name, whatsapp, sapaan from $table_name4 where group_id='$group_id' ");

		        if($data_by_group!=null){

		        	
		        	$no=1;
		        	foreach($data_by_group as $row){

		        		// ambil dari message custom
						if($followup_number=='6'){

							$data_field = array();
						    $data_field[ '{name}' ] 	= $row->name;
						    $data_field[ '{sapaan}' ] 	= $row->sapaan;
						    $data_field[ '{salam}' ] 	= $row->sapaan;

						    $messagenya = strtr(urldecode($message), $data_field);

							$data_array = [$messagenya, $row->whatsapp];
							djafunction_send_wa2($data_array);


						}else{ // ambil dari message follwup 1 s.d 5

						    // $followup_number : 1,2,3,4,5 

						    // GET SETTINGS
						    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="text_f1" or type="text_f2" or type="text_f3" or type="text_f4" or type="text_f5" ORDER BY id ASC');
						    $text_f1 = $query_settings[0]->data;
						    $text_f2 = $query_settings[1]->data;
						    $text_f3 = $query_settings[2]->data;
						    $text_f4 = $query_settings[3]->data;
						    $text_f5 = $query_settings[4]->data;

						    if($followup_number=='1'){
						    	$message = $text_f1;
						    }elseif($followup_number=='2'){
						    	$message = $text_f2;
						    }elseif($followup_number=='3'){
						    	$message = $text_f3;
						    }elseif($followup_number=='4'){
						    	$message = $text_f4;
						    }else{
						    	$message = $text_f5;
						    }

						    $data_field = array();
						    $data_field[ '{name}' ] 	= $row->name;
						    $data_field[ '{sapaan}' ] 	= $row->sapaan;
						    $data_field[ '{salam}' ] 	= $row->sapaan;

						    $messagenya = strtr(urldecode($message), $data_field);

							$data_array = [$messagenya, $row->whatsapp];
							djafunction_send_wa2($data_array);

						}

						if($broadcast_mode=='in_batch'){
							if ($no % $batch_size == 0) {
								if($send_delay>=1){
									sleep($send_delay);
								}else{
									usleep($send_delay * 1000000);
								}
						    }
						}elseif($broadcast_mode=='one_by_one'){
							if($send_delay>=1){
								sleep($send_delay);
							}else{
								usleep($send_delay * 1000000);
							}
						}else{
							// broadcast all
						}

					    $no++;
		        	}
		        	
		        }

			}

		}

    } else {
        error_log('Argumen tidak ditemukan.');
    }

}


function donasiaja_followup_function($followup_number) {

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_settings";
    $table_name2 = $wpdb->prefix . "dja_donate";

	$query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="automatic_followup_settings" or type="daily_followup" ORDER BY id ASC');
    
    $automatic_followup_settings = $query_settings[0]->data;
    $daily_followup = json_decode($query_settings[1]->data, true);

    // get time {"f1":["on","daily","05:05","1","broadcast_mode","batch_size","send_delay"],"f2":[]}
    $time 			= $daily_followup['f'.$followup_number][2]; 
    $broadcast_mode = $daily_followup['f'.$followup_number][4];
    $batch_size 	= (int) ($daily_followup['f' . $followup_number][5] ?? 0);
    $send_delay 	= (int) ($daily_followup['f' . $followup_number][6] ?? 0);

    // $filter_datestart_now = date("Y-m-d $time");
    // $filter_datestart_before = date("Y-m-d $time", strtotime($filter_datestart_now. ' - '.$followup_number.' days'));

    // if($followup_number=='1'){
    // 	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name2 where (f1 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
	// }elseif($followup_number=='2'){
    // 	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name2 where (f1 IS NOT NULL AND f2 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
	// }elseif($followup_number=='3'){
    // 	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name2 where (f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
	// }elseif($followup_number=='4'){
    // 	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name2 where (f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
	// }else{
    // 	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp from $table_name2 where (f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NOT NULL AND f5 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
	// }

	$followup_number = (int) $followup_number;

	$now = strtotime(date("Y-m-d $time"));
	$start = date("Y-m-d H:i:s", strtotime("-$followup_number days", $now));
	$end = date("Y-m-d H:i:s", strtotime("-" . ($followup_number - 1) . " days", $now));

	$where_clause = "status='0' AND created_at BETWEEN '$start' AND '$end'";

	if($followup_number=='1'){
	    $where_clause = "(f1 IS NULL) AND $where_clause";
	}elseif($followup_number=='2'){
	    $where_clause = "(f1 IS NOT NULL AND f2 IS NULL) AND $where_clause";
	}elseif($followup_number=='3'){
	    $where_clause = "(f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NULL) AND $where_clause";
	}elseif($followup_number=='4'){
	    $where_clause = "(f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NULL) AND $where_clause";
	}else{
	    $where_clause = "(f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NOT NULL AND f5 IS NULL) AND $where_clause";
	}

	$query_donate = $wpdb->get_results("SELECT id, name, whatsapp FROM $table_name2 WHERE $where_clause");


    if($query_donate!=null){
    	foreach($query_donate as $row){

			$data_array = [$row->id, $followup_number, 'followup_onetofive'];
		    djafunction_send_wa($data_array);

		    if($broadcast_mode=='in_batch'){
				if ($no % $batch_size == 0) {
					if($send_delay>=1){
						sleep($send_delay);
					}else{
						usleep($send_delay * 1000000);
					}
			    }
			}elseif($broadcast_mode=='one_by_one'){
				if($send_delay>=1){
					sleep($send_delay);
				}else{
					usleep($send_delay * 1000000);
				}
			}else{
				// broadcast all
			}

    	}
    }
	
}




