	}else{

		$time = $daily_followup['f'.$followup_number][2]; // get time {"f1":["on","daily","05:05","1"],"f2":[]}
	}

    // $followup_number = $data;

    if($target=='campaign'){ // yang target: di "campaign". gak pakai filter date

