    $message = strtr($message, $data_field);
	$messagenya = dja_whatsapp_format($message);
	$messagenya = str_replace("\\", '', $messagenya);
	$messagenya = str_replace("&#39;", "'", $messagenya);
	$messagenya = strip_tags($messagenya);

    $phone = djaPhoneFormat($whatsapp_number,$currency);

	if($wanotif_apikey!='' && $wanotif_on=='1'){

		// send with wanotif
		$url = $wanotif_url.'/send';
		$messagenya = $message;
		$messagenya = str_replace("&#39;", "'", $messagenya);

		$curl = curl_init();
		curl_setopt($curl, CURLOPT_URL, $url);
		curl_setopt($curl, CURLOPT_HEADER, 0);
		curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1);
		curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 2);
		curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
		curl_setopt($curl, CURLOPT_TIMEOUT,30);
		curl_setopt($curl, CURLOPT_POST, 1);
		curl_setopt($curl, CURLOPT_POSTFIELDS, array(
		    'Apikey'    => $wanotif_apikey,
		    'Phone'     => $phone,
		    'Message'   => $messagenya,
		));
		$response = curl_exec($curl);
		curl_close($curl);

		$array = json_decode( $response, true );
		$data = $array['wanotif']['status'];

		if($data=='sent'){
			ob_clean();
			echo 'success';
		}else{
			ob_clean();
			echo 'failed';
		}


    }

    if($action=='ajax'){
    	wp_die();
    }

} 
add_action( 'wp_ajax_djafunction_send_wa2', 'djafunction_send_wa2' );
add_action( 'wp_ajax_nopriv_djafunction_send_wa2', 'djafunction_send_wa2' );


function set_metapixel_convertion($email, $phone, $fname, $lname, $currency, $total, $donate_id){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";
    $table_name2 = $wpdb->prefix . "dja_campaign";
    $table_name3 = $wpdb->prefix . "dja_settings";

    $row = $wpdb->get_results('SELECT a.*, b.pixel_status, b.fb_event, b.metapixel_convertion, b.metapixel_convertion_data  from '.$table_name.' a 
    left JOIN '.$table_name2.' b ON b.campaign_id = a.campaign_id where a.id="'.$donate_id.'" ')[0];

    // di set berdasarkan metapixel di campaign dahulu
    if($row->pixel_status=='1' and $row->metapixel_convertion=='1'){
    	// get sum pixel
        if($row->metapixel_convertion_data!=''){
            $metapixel_convertion_data = json_decode($row->metapixel_convertion_data, true);
            $jumlah_pixel = $metapixel_convertion_data['jumlah'];
        }else{
            $jumlah_pixel = 0;
        }

        // get event success or event ke 4
        $fb_event  = json_decode($row->fb_event, true);
	    if(isset($fb_event['event'][3])){
	        $event_4  = $fb_event['event'][3];
	    }else{
	        $event_4  = 'Donate';
	    }
        
        
        $fb_pixel_convertion = '';
        if($jumlah_pixel>=1){
            
            foreach ($metapixel_convertion_data['data'] as $key => $value) {

            	$pixel_id 		= $value[0];
                $access_token 	= $value[1];
                $test_event_code = $value[2];

                $payload = array(
					'data' => array(
						array(
							'event_name' => $event_4,
							'event_time' => time(),
							'user_data' => array(
								'em' => hash('sha256', $email),
				                'ph' => hash('sha256', $phone),
				                'fn' => hash('sha256', $fname),
				                'ln' => hash('sha256', $lname)
							),
							'custom_data' => array(
								'currency' => $currency,
								'value' => $total
							),
				            'action_source' => 'website'
						)
					),
					'test_event_code' => $test_event_code
				);

				// Konversi payload ke JSON
				$payload_json = json_encode($payload);

				// Endpoint Facebook Conversion API
				$url = 'https://graph.facebook.com/v19.0/'.$pixel_id.'/events?access_token='.$access_token;

				// Inisialisasi cURL
				$ch = curl_init();

				// Set konfigurasi cURL
				curl_setopt($ch, CURLOPT_URL, $url);
				curl_setopt($ch, CURLOPT_POST, true);
				curl_setopt($ch, CURLOPT_POSTFIELDS, $payload_json);
				curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/json'));

				// Eksekusi permintaan cURL
				$result = curl_exec($ch);

				// Tangani respons
				// if ($result !== false) {
				// 	echo 'Konversi berhasil terkirim.';
				// } else {
				// 	echo 'Terjadi kesalahan saat mengirim acara konversi: ' . curl_error($ch);
				// }

				// Tutup koneksi cURL
				curl_close($ch);

            }
        }
        

    }else{

    	// klo tidak, di set berdasarkan settingan general
    	// Settings
	    $query_settings = $wpdb->get_results('SELECT data from '.$table_name3.' where type="fb_event" or type="metapixel_only" or type="metapixel_convertion" or type="metapixel_convertion_data" ORDER BY id ASC');
	    $fb_event 	 				= json_decode($query_settings[0]->data, true);
	    $metapixel_only             = $query_settings[1]->data;
	    $metapixel_convertion       = $query_settings[2]->data;
	    $metapixel_convertion_data  = $query_settings[3]->data;

	    // GET EVENT
	    if(isset($fb_event['event'][3])){
	        $event_4  = $fb_event['event'][3];
	    }else{
	        $event_4  = 'Donate';
	    }

	    
	    // meta pixel convertion - general
	    if($metapixel_convertion=='1'){
	        if($metapixel_convertion_data!=''){
	            $metapixel_convertion_data = json_decode($metapixel_convertion_data, true);
	            $jumlah_pixel = $metapixel_convertion_data['jumlah'];
	        }else{
	            $jumlah_pixel = 0;
	        }
	        
	        if($jumlah_pixel>=1){
	            
	            foreach ($metapixel_convertion_data['data'] as $key => $value) {

	                $pixel_id 		= $value[0];
	                $access_token 	= $value[1];
	                $test_event_code = $value[2];

	                $payload = array(
						'data' => array(
							array(
								'event_name' => $event_4,
								'event_time' => time(),
								'user_data' => array(
									'em' => hash('sha256', $email),
					                'ph' => hash('sha256', $phone),
					                'fn' => hash('sha256', $fname),
					                'ln' => hash('sha256', $lname)
								),
								'custom_data' => array(
									'currency' => $currency,
									'value' => $total
								),
					            'action_source' => 'website'
							)
						),
						// 'test_event_code' => 'TEST10146' // Kode peristiwa uji (opsional)
						'test_event_code' => $test_event_code
					);

					// Konversi payload ke JSON
					$payload_json = json_encode($payload);

					// Endpoint Facebook Conversion API
					$url = 'https://graph.facebook.com/v19.0/'.$pixel_id.'/events?access_token='.$access_token;

					// Inisialisasi cURL
					$ch = curl_init();

					// Set konfigurasi cURL
					curl_setopt($ch, CURLOPT_URL, $url);
					curl_setopt($ch, CURLOPT_POST, true);
					curl_setopt($ch, CURLOPT_POSTFIELDS, $payload_json);
					curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/json'));

					// Eksekusi permintaan cURL
					$result = curl_exec($ch);

					// Tutup koneksi cURL
					curl_close($ch);
	            }
	        }

	    }
	    

    }


}


function get_firstname($name){
	$count_name = str_word_count($name);
    if($count_name==1){
    	$user_firstname = $name;
    	$user_lastname = '';
    }elseif($count_name==2){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1];
    }elseif($count_name==3){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1].' '.$name[2];
    }elseif($count_name==4){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1].' '.$name[2].' '.$name[3];
    }elseif($count_name==5){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1].' '.$name[2].' '.$name[3].' '.$name[4];
    }else{
    	$user_firstname = $name;
    	$user_lastname = '';
    }

    return $user_firstname;
}



function get_lastname($name){
	$count_name = str_word_count($name);
    if($count_name==1){
    	$user_firstname = $name;
    	$user_lastname = '';
    }elseif($count_name==2){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1];
    }elseif($count_name==3){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1].' '.$name[2];
    }elseif($count_name==4){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1].' '.$name[2].' '.$name[3];
    }elseif($count_name==5){
    	$name = explode(' ',$name);
	    $user_firstname = $name[0];
    	$user_lastname = $name[1].' '.$name[2].' '.$name[3].' '.$name[4];
    }else{
    	$user_firstname = $name;
    	$user_lastname = '';
    }

    return $user_lastname;
}


function djafunction_set_payment() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";
    $table_name2 = $wpdb->prefix . "dja_settings";
    $table_name3 = $wpdb->prefix . "dja_campaign";
    $table_name4 	= $wpdb->prefix . "dja_aff_submit";
    $table_name5 	= $wpdb->prefix . "dja_aff_code";

    // FROM INPUT
    $donasi_id  = $_POST['datanya'][0];
    $value_button = $_POST['datanya'][1];
	
	// GET SETTINGS
	$query_settings = $wpdb->get_results('SELECT data from '.$table_name2.' where type="text_received" or type="text_received_status" or type="currency" or type="wanotif_url" or type="wanotif_apikey" or type="wanotif_message" or type="wanotif_on_dashboard" or type="wanotif_on" or type="email_on" or type="email_success_message" or type="wanotif_apikey_cs" ORDER BY id ASC');
    $text_received 		  = $query_settings[0]->data;
    $text_received_status = $query_settings[1]->data;
    $currency 			  = $query_settings[2]->data;
    $wanotif_url 		  = $query_settings[3]->data;
    $wanotif_apikey 	  = $query_settings[4]->data;
    $wanotif_message 	  = $query_settings[5]->data;
    $wanotif_on_dashboard = $query_settings[6]->data;
    $wanotif_on 		  = $query_settings[7]->data;
    $email_on 		  	  = $query_settings[8]->data;
    $email_success_message= $query_settings[9]->data;
    $wanotif_apikey_cs 	  = $query_settings[10]->data;


    $row = $wpdb->get_results('SELECT a.*, b.title, b.slug from '.$table_name.' a 
    left JOIN '.$table_name3.' b ON b.campaign_id = a.campaign_id where a.id="'.$donasi_id.'" ')[0];

    $data_field = array();
    $data_field[ '{name}' ] 	= $row->name;
    $data_field[ '{sapaan}' ] 	= $row->sapaan;
    $data_field[ '{salam}' ] 	= $row->sapaan;
    $data_field[ '{whatsapp}' ] = $row->whatsapp;
    $data_field[ '{email}' ] 	= $row->email;
    $data_field[ '{comment}' ] 	= $row->comment;
    $data_field[ '{payment_number}' ] 	= $row->payment_number;
    $data_field[ '{payment_code}' ] 	= paymentCode($row->payment_code);
    $data_field[ '{payment_account}' ] 	= $row->payment_account;
    $data_field[ '{campaign_title}' ] 	= $row->title;
    $data_field[ '{campaign_url}' ] 	= get_site_url().'/campaign/'.$row->slug;
    $data_field[ '{invoice_id}' ] 		= $row->invoice_id;
    $data_field[ '{date}' ] 			= $datenya = date("j F Y - H:i",strtotime($row->created_at));
    $data_field[ '{link_ekuitansi}' ] 	= get_site_url().'/ekuitansi/'.$row->invoice_id;
    $data_field[ '{link_sertifikat}' ] 	= get_site_url().'/sertifikat/'.$row->invoice_id;
    
    if($currency=='IDR'){
    	$data_field[ '{total}' ] 	= 'Rp '.number_format_currency($row->nominal);
    }elseif($currency=='MYR'){
    	$data_field[ '{total}' ] 	= 'RM '.number_format_currency($row->nominal);
    }else{
    	$data_field[ '{total}' ] 	= $row->nominal;
    }

    // GET DATA CAMPAIGN
    $campaign_id = $row->campaign_id;
    $query_campaign = $wpdb->get_results('SELECT followup_status, followup_text, user_id from '.$table_name3.' 
    where campaign_id="'.$campaign_id.'" ');

    // SET TEXT FOLLOWUP BERDASARKAN CUSTOM MULTIPLE FOLLOWUP CAMPAIGN FORMAT
    $payment_success_message = '';
    if (!empty($query_campaign) && isset($query_campaign[0]->followup_status, $query_campaign[0]->followup_text)) {

	    $followup_status = $query_campaign[0]->followup_status;
	    $followup_text = $query_campaign[0]->followup_text;

	    $data_json_followup = json_decode($followup_text, true);
	    
		if (isset($data_json_followup['data'][5])) {
		    $payment_success_message = $data_json_followup['data'][5]['message'];
		}

	}

	if($text_received_status=='1'){
		if($followup_status=='1'){
		    $text_wa = urldecode($payment_success_message);
		    
		}else{
			$text_wa = $text_received;
		}
    	
    }else{
    	$text_wa = '';
    }


    $query_donation = $wpdb->get_results("SELECT b.user_id as fundraiser_id FROM $table_name4 a
    LEFT JOIN $table_name5 b ON b.id = a.affcode_id 
    where a.donate_id='$donasi_id' ORDER BY a.id DESC");

    if (!empty($query_donation) && isset($query_donation[0]->fundraiser_id)) {
    	
    	$fundraiser_id = $query_donation[0]->fundraiser_id;
    
	    if (!empty($fundraiser_id)) {
	        $user_info = get_userdata($fundraiser_id);
	        $fundraiser_name = trim($user_info->first_name . ' ' . $user_info->last_name);
	        $data_field[ '{fundraiser}' ] = !empty($fundraiser_name) ? $fundraiser_name : '-';
	    } else {
	        $data_field[ '{fundraiser}' ] = '-';
	    }

	} else {
	    $data_field[ '{fundraiser}' ] = '-';
	}

	if (isset($query_campaign[0]->user_id)) {
        $user_info = get_userdata($query_campaign[0]->user_id);
        $campaigner_name = trim($user_info->first_name . ' ' . $user_info->last_name);
        $data_field[ '{campaigner}' ] = !empty($campaigner_name) ? $campaigner_name : '-';
    } else {
        $data_field[ '{campaigner}' ] = '-';
    }
    

    $phone = djaPhoneFormat($row->whatsapp,$currency);



    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];
    $id_login = wp_get_current_user()->ID;

    if($role=='donatur'){
    	$set_by = 'donatur-id:'.$id_login;
    }else{
    	$set_by = 'admin';
    }
    
    if($value_button=='1'){
    	$wpdb->update(
	        $table_name,
	        array(
	            'status' 	 => 1,
	            'payment_at' => date("Y-m-d H:i:s"),
	            'process_by' => $set_by
	        ), array('id' => $donasi_id), array('%s'), array('%s')
	    );
    }else{
    	$wpdb->update(
	        $table_name,
	        array(
	            'status' 	 => 0,
	            'payment_at' => null,
	            'process_by' => null
	        ), array('id' => $donasi_id), array('%s'), array('%s')
	    );
    }

    if($value_button=='1'){

	    $m  = $row->email;
	    $ph = $phone;
	    $fn = get_firstname($row->name);
	    $ln = get_lastname($row->name);
	    $total = $row->nominal;

	    set_metapixel_convertion($m, $ph, $fn, $ln, $currency, $total, $donasi_id);

    }
    

    // send email
    if($email_on=='1'){

    	$email_success_message = json_decode($email_success_message);

		foreach($email_success_message as $key => $value) {

            $message = $value->message;
            $message = strtr($message, $data_field);
			$message = str_replace('<p>linebreak</p>', '', $message);
			$message = str_replace('linebreak', '', $message);
			
            $subject = $value->subject;
            $subject = strtr($subject, $data_field);
			$subject = str_replace("'","",$subject);
			
            $emailnya = $value->email;
			
            $emailnyacc = $value->emailcc;
            $emailnyabcc = $value->emailbcc;

            $headers[] = 'Content-Type: text/html; charset=UTF-8';

            $body = '<!DOCTYPE html><html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:o="urn:schemas-microsoft-com:office:office"><head><meta charset="utf-8"> <meta name="viewport" content="width=device-width,initial-scale=1"> <meta name="x-apple-disable-message-reformatting"> <title></title><!--[if mso]> <style>table{border-collapse:collapse;border-spacing:0;border:none;margin:0;}div, td{padding:0;}div{margin:0 !important;}</style> <noscript> <xml> <o:OfficeDocumentSettings> <o:PixelsPerInch>96</o:PixelsPerInch> </o:OfficeDocumentSettings> </xml> </noscript><![endif]--> <style>table, td, div, h1, p{font-family: Arial, sans-serif;}@media screen and (max-width: 530px){.unsub{display: block; padding: 8px; margin-top: 14px; border-radius: 6px; background-color: #F1F7FB; text-decoration: none !important; font-weight: bold;}.col-lge{max-width: 100% !important;}}@media screen and (min-width: 531px){.col-sml{max-width: 27% !important;}.col-lge{max-width: 73% !important;}}</style></head><body style="margin:0;padding:0;word-spacing:normal;background-color:#E7ECF0;"> <div role="article" aria-roledescription="email" lang="en" style="text-size-adjust:100%;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;background-color:#E7ECF0;"> <table role="presentation" style="width:100%;border:none;border-spacing:0;"><tr><td style="padding:30px;background-color:#E7ECF0;"></td></tr><tr><td align="center" style="padding:0;"><!--[if mso]> <table role="presentation" align="center" style="width:600px;"> <tr> <td><![endif]--> <table role="presentation" style="width:94%;max-width:600px;border:none;border-spacing:0;text-align:left;font-family:Arial,sans-serif;font-size:15px;line-height:22px;color:#363636;"> <tr><td style="padding:30px;background-color:#ffffff;"><h1 style="margin-top:0;margin-bottom:16px;font-size:21px;line-height:32px;font-weight:bold;letter-spacing:-0.02em;">'.$subject.'</h1>'.$message.'</td></tr><tr><td style="padding:30px;background-color:#E7ECF0;"></td></tr></table><!--[if mso]> </td></tr></table><![endif]--> </td></tr></table> </div></body></html>';

			if (strpos($emailnyacc, ',') !== false ) {
				$array_emailcc  = (explode(",", $emailnyacc));
				foreach ($array_emailcc as $values){
					$email_cc = strtr($values, $data_field);
					$headers[] = 'Cc: '.$email_cc;
				}
			}else{
				$emailnyacc = strtr($emailnyacc, $data_field);
				$headers[] = 'Cc: '.$emailnyacc;
			}

			if (strpos($emailnyabcc, ',') !== false ) {
				$array_emailbcc  = (explode(",", $emailnyabcc));
				foreach ($array_emailbcc as $values){
					$email_bcc = strtr($values, $data_field);
					$headers[] = 'Bcc: '.$email_bcc;
				}
			}else{
				$emailnyabcc = strtr($emailnyabcc, $data_field);
				$headers[] = 'Bcc: '.$emailnyabcc;
			}
			
 			
			if($emailnya!=''){
				$emailnya = strtr($emailnya, $data_field);
				wp_mail( $emailnya, $subject, $body, $headers );
			}
				
		}

	}

	// cek cs rotator
   	// With Wanotif
	if($wanotif_apikey!='' && $wanotif_on=='1' && $value_button=='1' && $text_received_status=='1' && $wanotif_on_dashboard=='1'){
		// SET PHONE
		if($row->whatsapp!=''){

			// device id diambil dari cs id table donate
			if($row->cs_id!=null){
                $data_cs = json_decode($wanotif_apikey_cs, true);

            	foreach ($data_cs['data'] as $key => $value) {
                	if($row->cs_id==$value[0]){
                		$wanotif_apikey_cs = $value[1];
                		if($wanotif_apikey_cs!=''){
							$wanotif_apikey = $wanotif_apikey_cs;
						}
						break;
                	}
                }
			}


			$phone = djaPhoneFormat($row->whatsapp,$currency);
			$url = $wanotif_url.'/send';

			$messagenya = $text_wa;
			$messagenya = strtr($messagenya, $data_field);
			$messagenya = str_replace("&#39;", "'", $messagenya);

			$curl = curl_init();
			curl_setopt($curl, CURLOPT_URL, $url);
			curl_setopt($curl, CURLOPT_HEADER, 0);
			curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1);
			curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 2);
			curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
			curl_setopt($curl, CURLOPT_TIMEOUT,30);
			curl_setopt($curl, CURLOPT_POST, 1);
			curl_setopt($curl, CURLOPT_POSTFIELDS, array(
			    'Apikey'    => $wanotif_apikey,
			    'Phone'     => $phone,
			    'Message'   => $messagenya,
			));
			$response = curl_exec($curl);
			curl_close($curl);
			ob_clean();
			echo 'wanotif_';

		}else{
			ob_clean();
			echo 'wanotiffalse_';
		}

	}else{

		$message = strtr($text_wa, $data_field);
		$message = dja_whatsapp_format($message);
		$message = str_replace("\\", '', $message);
		$message = str_replace("&#39;", "'", $message);
		$message = str_replace("{hide_qr}", "", $message);
		$message = strip_tags($message);

		$urllink_whatsapp = 'https://api.whatsapp.com/send?phone='.$phone.'&text='.$message;
		ob_clean();
		echo 'success_'.$urllink_whatsapp;

	}

    wp_die();

} 
