function number_format_currency($nominal){
	// global $wpdb;
    // $table_name = $wpdb->prefix . "dja_settings";

	// $query_currency = $wpdb->get_results('SELECT data from '.$table_name.' where type="currency"  ORDER BY id ASC');
    // $currency = $query_currency[0]->data;

    // if($currency=='MYR'){
	// 	return number_format($nominal,0,",",",");
	// }else{
    //     return number_format($nominal,0,",",".");
    // }

    if($nominal==null || $nominal==''){
    	$nominal = 0;
    }

    global $wpdb;
    $table_name = $wpdb->prefix . "dja_settings";

    $query_currency = $wpdb->get_results('SELECT data from '.$table_name.' where type="currency" ORDER BY id ASC');
    $currency = $query_currency[0]->data;

    // Check if $nominal is null, and if so, set it to 0 or handle it as needed
    if (is_null($nominal)) {
        $nominal = 0; // or handle the null case in another way
    }

    if ($currency == 'MYR') {
        return number_format($nominal, 0, ",", ",");
    } else {
        return number_format($nominal, 0, ",", ".");
    }

}


function number_format_currency_percentage($nominal){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_settings";

	$query_currency = $wpdb->get_results('SELECT data from '.$table_name.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;

    if($currency=='MYR'){
		return number_format($nominal,1,".",",");
	}else{
        return number_format($nominal,1,",",".");
    }
}




