function djafunction_update_password() {
    global $wpdb;
    $table_name = $wpdb->prefix . "users";

    $id_login = wp_get_current_user()->ID;
    
    // FROM INPUT
    $user_id 	= $_POST['datanya'][0];
    $user_pass_new 	= $_POST['datanya'][1];

    if($id_login==$user_id){
 
	    $hash = wp_hash_password( $user_pass_new );
	    $wpdb->update(
	        $table_name,
	        array(
	            'user_pass'           => $hash
	        ),
	        array( 'ID' => $user_id )
	    );
	 		
	 	clean_user_cache( $user_id );

	 	ob_clean();
	 	echo 'success';
	}

	wp_die();

}
add_action( 'wp_ajax_djafunction_update_password', 'djafunction_update_password' );
add_action( 'wp_ajax_nopriv_djafunction_update_password', 'djafunction_update_password' ); 




function djafunction_update_instruction() {
    global $wpdb;
    
    // FROM INPUT
    $newContent = $_POST['datanya'][0];
    $newContent = str_replace('\\', '', $newContent);
    $newContent = json_decode($newContent);
    $newContent = json_encode($newContent);

    // $data = json_encode($json);
    $filePath = plugin_dir_url( __FILE__ )."library/instructions.json";


    $result = file_put_contents($filePath, $newContent);

	// Prepare the response
	if ($result !== false) {
		ob_clean();
		echo 'success';
	} else {
		echo $newContent;
  	}
	
	wp_die();

}
add_action( 'wp_ajax_djafunction_update_instruction', 'djafunction_update_instruction' );
