	                    	}else{
	                    		$img_confirmation = '<div class='."'".'detail_donasi img_confirmation '.$status_img."'".' data-id='."'".$row->donate_id."'".' title='."'".'Check Confirmation'."'".' style='."'".''."'".'><div style='."cursor:pointer;font-size:9px;padding:1px 8px 3px 16px;border-radius:10px;".'><i class='."'".'mdi mdi-checkbox-marked-circle-outline'."'".' style='."color:#36BD47!important;margin-left:-10px;margin-right:4px;".'></i>Bukti&nbsp;Transfer</div></div>';
	                    	}
	                    	
		                }

		                $info_qurban = json_decode($row->info_qurban, true);
					    $datane2 = '<ul style='."'".'margin-bottom:0px;margin-top:3px;'."'".'>';
					    $count_qurban = 0;
					    foreach ( $info_qurban as $key => $value ) {
					    	$show_qurban = '';
