                    $button_action = '<div class='."'".'btn-group mb-4'."'".' role='."'".'group'."'".' aria-label='."'".'Basic example'."'".'><button '.$button_restore.' type='."'".'button'."'".' class='."'".'btn btn-outline-light restore_data'."'".' data-action='."'".'ontrash'."'".' data-id='."'".$row->id."'".' title='."'".$button_restore_title."'".' style='."'".'border-top-right-radius:0;border-bottom-right-radius:0;'."'".'><i class='."'".'mdi mdi-restore mr-2'."'".' style='."'".'margin: 0 4px 0 2px !important;color:'.$button_restore_color.';'."'".'></i></button><button type='."'".'button'."'".' class='."'".'btn btn-outline-light del_donasi'."'".' data-id='."'".$row->id."'".' title='."'".'Delete Permanently'."'".'><i class='."'".'mdi mdi-trash-can mr-2'."'".' style='."'".'margin: 0 4px 0 2px !important;color:#EF4D56;'."'".'></i></button></div>';

				    echo '
				    {
				      "no": "<span data-id='."'".$row->id."'".'>'.$no.'</span>",
				      "picture": "'.$pp.'",
				      "name": "'.str_replace('\\', '', $donatur_name).$datane2.'",
				      "whatsapp": "'.$whatsapp.'",
				      "total_donate": "'.$nominal_donasi.$donasi_payment_info.'",
				      "program": "'.$title_campaign.'",
				      "payment_status": "'.$payment_status.$img_confirmation.'",';
				      echo '
				      "date": "'.$date_deleted.'",';
				      echo '"cs": "'.str_replace('\\', '', $row->who_del_name).'"';
