function dja_get_data_ip(){

	set_time_donasiaja();

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_campaign";
    $table_name2 = $wpdb->prefix . "dja_category";
    $table_name3 = $wpdb->prefix . "dja_campaign_update";
    $table_name4 = $wpdb->prefix . "dja_donate";
    $table_name5 = $wpdb->prefix . "dja_settings";
    $table_name6 = $wpdb->prefix . "dja_users";
    $table_name7 = $wpdb->prefix . "users";
    $table_name8 = $wpdb->prefix . "dja_payment_log";
    $table_name9 = $wpdb->prefix . "dja_blocked_ip";

    $startlist 	  = $_POST['start'];
    $length 	  = $_POST['length'];
    $draw 		  = $_POST['draw'];

    $c_id 		  = $_POST['c_id'];
    $date_filter  = $_POST['date_filter'];
    $date_range   = $_POST['date_range'];
    $search_value = $_POST['search']['value'];

    $status 	  = $_POST['status'];

    if($status=='blocked'){
    	$status = 1;
    }else{
    	$status = 0;
    }

    // Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name5.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $show_currency = donasiaja_currency($currency);
    $show_currency2 = donasiaja_currency2($currency);

    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DNA . 'library/locale/'.$lang.'.php');

    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];
    $id_login = wp_get_current_user()->ID;


    if($c_id=='all'){
    	$c_id = null;
    }

    $limit = '';
    if($length==-1){
		$limit = '';
	}else{
		$limit = "LIMIT $startlist,$length";
	}


    $search_filter = '';
    if($search_value!=''){
    	$search_filter = "and (ip like '%$search_value%' or note like '%$search_value%') ";
    }

    $data_ip = $wpdb->get_results("
        SELECT a.* from $table_name9 a 
        WHERE a.id != ''
        AND status = '$status'
        $search_filter
        ORDER BY a.id DESC $limit");

    $jumlah_total = $wpdb->get_results("
        SELECT count(a.id) as idnya from $table_name9 a 
        WHERE a.id != '' 
        AND status = '$status' 
        $search_filter ORDER BY a.id DESC")[0]->idnya;


	$no = 1+$startlist;
	$len = count($data_ip)+$startlist;

		ob_clean();
		echo '{
			"draw": '.$draw.',
			"recordsTotal": '.$jumlah_total.',
			"recordsFiltered": '.$jumlah_total.',
			"data": [';

			  	foreach ($data_ip as $row) {

			  		$user_info = get_userdata($row->created_by);
			  		if($user_info!=null){
			  			$fullname = $user_info->first_name.' '.$user_info->last_name;
			  		}else{
			  			$fullname = '-';
			  		}
				    

                    $button_action = '<div class='."'".'btn-group mb-2'."'".' role='."'".'group'."'".' aria-label='."'".'Basic example'."'".' style='."'".'margin-top:-5px;'."'".'><button '.$button_restore.' type='."'".'button'."'".' class='."'".'btn btn-outline-light edit_ip'."'".' data-action='."'".'ontrash'."'".' data-id='."'".$row->id."'".' title='."'".$button_restore_title."'".' style='."'".'border-top-right-radius:0;border-bottom-right-radius:0;'."'".'><i class='."'".'mdi mdi-pencil mr-2'."'".' style='."'".'margin: 0 4px 0 2px !important;color:'.$button_restore_color.';'."'".'></i></button><button type='."'".'button'."'".' class='."'".'btn btn-outline-light del_ip'."'".' data-id='."'".$row->id."'".' title='."'".'Delete Permanently'."'".'><i class='."'".'mdi mdi-trash-can mr-2'."'".' style='."'".'margin: 0 4px 0 2px !important;color:#EF4D56;'."'".'></i></button></div>';

                    $readtime = new humanReadtime();
                    $a = $readtime->dja_human_time($row->created_at);

					$datenya = new DateTime($row->created_at);
                    $blocked_time = '<span class=date_donasi>'.$datenya->format('d').'&nbsp;'.$datenya->format('M').',&nbsp;'.$datenya->format('Y').'&nbsp;-&nbsp;'.$datenya->format('H').':'.$datenya->format('i').'</span><br><span style='."'".'font-size:10px;color:#91a2b0;'."'".'>'.$a.'<span>';

				    echo '
				    {
				      "no": "<span data-id='."'".$row->id."'".'>'.$no.'</span>",
				      "ip": "'.$row->ip.'",
				      "note": "'.$row->note.'",
				      "date": "'.$blocked_time.'",';
				      echo '"created_by": "'.str_replace('\\', '', $fullname).'"';
				  	  if($role=='donatur' || $role=='cs'){echo'';}else{echo ',"action": "'.$button_action.'"';}
				      
				  	echo '
				    }';

				    if($len==$no){echo'';}else{echo',';} // add koma
                    $no++;

				}

			echo '
			  ]
		}';

		

	wp_die();

}

add_action( 'wp_ajax_dja_get_data_ip', 'dja_get_data_ip' );
add_action( 'wp_ajax_nopriv_dja_get_data_ip', 'dja_get_data_ip' );



