				    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiaja_campaign id=" . $row->campaign_id . " show=short_form title_image=true]' title='Copy Shortcode'>Short Form 2</a>";
