function djafunction_update_group_name(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dja_group_list";
    $table_name2 = $wpdb->prefix . "dja_settings";

    // FROM INPUT
    $id 		= $_POST['datanya'][0];
    $group_name = $_POST['datanya'][1];


    if($id=='0'){

	    $a = $wpdb->insert(
            $table_name, //table
            array(
	            'group_name' 	=> $group_name,
	            'created_at' 	=> date("Y-m-d H:i:s")),
            array('%s', '%s') //data format         
        );

        $lastid = $wpdb->insert_id;

    }else{
    	$a = $wpdb->update(
	        $table_name, //table
	        array(
	            'group_name' 	 => $group_name
	        ),
	        array('id' => $id), //where
	        array('%s'), //data format
	        array('%s') //where format
	    );

	    $lastid = $id;
    }

	if ($a === false) {
	    $info = 'error';
	} elseif ($a === 0) {
	    $info = 'success';
	} else {
	    $info = 'success';
	}

    echo $info.'_'.$lastid;

    wp_die();

}
