function dja_get_data_fundraising(){

	global $wpdb;
	donasiaja_global_vars();
    $table_name = $wpdb->prefix . "dja_campaign";
    $table_name2 = $wpdb->prefix . "dja_category";
    $table_name3 = $wpdb->prefix . "dja_campaign_update";
    $table_name4 = $wpdb->prefix . "dja_donate";
    $table_name5 = $wpdb->prefix . "dja_settings";
    $table_name6 = $wpdb->prefix . "dja_users";
    $table_name7 = $wpdb->prefix . "dja_payment_list";
    $table_name8 = $wpdb->prefix . "dja_aff_code";
    $table_name9 = $wpdb->prefix . "dja_aff_submit";
    $table_name10 = $wpdb->prefix . "dja_aff_click";
    $table_name11 = $wpdb->prefix . "dja_aff_payout";
    $table_name12 = $wpdb->prefix . "users";


    $startlist 	  = $_POST['start'];
    $length 	  = $_POST['length'];
    $draw 		  = $_POST['draw'];
    $c_id 		  = $_POST['c_id'];
    $date_filter  = $_POST['date_filter'];
    $date_range   = $_POST['date_range'];
    $search_value = $_POST['search']['value'];
    $set_as_user  = $_POST['as_user'];

    $limit = '';
    if($length==-1){
		$limit = '';
	}else{
		$limit = "LIMIT $startlist,$length";
	}

	// $search_filter = '';
    if($search_value!=''){

    	if($as_user==true) {

    		$data_campaignnya = $wpdb->get_results('SELECT id from '.$table_name.' where title like "%'.$search_value.'%"');
    		if($data_campaignnya!=null){
    			$s_id = $data_campaignnya[0]->id;
    		}else{
    			$s_id = 0;
    		}

    	}else{

	    	$search_user = false;
	    	$search_campaign = false;

			$data_usernya = $wpdb->get_results('SELECT ID from '.$table_name12.' where display_name like "%'.$search_value.'%"');
			if($data_usernya!=null){
				$id_user_search = $data_usernya[0]->ID;
				$search_user = true;
			}else{
				$data_campaignnya = $wpdb->get_results('SELECT id from '.$table_name.' where title like "%'.$search_value.'%"');
	    		if($data_campaignnya!=null){
	    			$s_id = $data_campaignnya[0]->id;
	    		}else{
	    			$s_id = 0;
	    		}
	    		$search_campaign = true;
			}


    	}
    	
    	
    }
    

    // ROLE
    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];

    $id_login = wp_get_current_user()->ID;

    $akses = 1;
    if($role=='donatur'){
        $usernya = $wpdb->get_results('SELECT * from '.$table_name6.' where user_id="'.$id_login.'"')[0];

        if($usernya->user_verification=='1'){
            $akses = 1;
        }else{
            $akses = 0;
        }
    }

