function dja_get_data_analytics(){

	set_time_donasiaja();

	global $wpdb;
    $table_name  = $wpdb->prefix . "dja_campaign";
    $table_name2 = $wpdb->prefix . "dja_category";
    $table_name3 = $wpdb->prefix . "dja_campaign_update";
    $table_name4 = $wpdb->prefix . "dja_donate";
    $table_name5 = $wpdb->prefix . "dja_settings";
    $table_name6 = $wpdb->prefix . "dja_users";
    $table_name7 = $wpdb->prefix . "users";
    $table_name8 = $wpdb->prefix . "dja_payment_log";

    $startlist 	  = $_POST['start'];
    $length 	  = $_POST['length'];
    $draw 		  = $_POST['draw'];
    $c_id 		  = $_POST['c_id'];
    $date_filter  = $_POST['date_filter'];
    $date_range   = $_POST['date_range'];
    $search_value = $_POST['search']['value'];

    // Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="form_setting" or type="btn_followup" or type="text_f1" or type="text_f2" or type="text_f3" or type="text_f4" or type="text_f5" or type="text_received" or type="text_received_status" or type="currency" or type="wanotif_on_dashboard"  ORDER BY id ASC');
    $form_setting = $query_settings[0]->data;
    $btn_followup = $query_settings[1]->data;
    $text_f1 = $query_settings[2]->data;
    $text_f2 = $query_settings[3]->data;
    $text_f3 = $query_settings[4]->data;
    $text_f4 = $query_settings[5]->data;
    $text_f5 = $query_settings[6]->data;
    $text_received = $query_settings[7]->data;
    $text_received_status = $query_settings[8]->data;
    $currency = $query_settings[9]->data;
    $wanotif_on_dashboard = $query_settings[10]->data;

    $show_currency = donasiaja_currency($currency);

    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];
    $id_login = wp_get_current_user()->ID;


    if($c_id=='all'){
    	$c_id = null;
    }

    $limit = '';
    if($length==-1){
		$limit = '';
	}else{
		$limit = "LIMIT $startlist,$length";
	}


    $filternya = "";
    if($date_filter=='today' || $date_filter=='yesterday' || $date_filter=='7lastdays' || $date_filter=='30lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='thisyear' || $date_filter=='lastyear' || $date_filter=='last2years' || $date_filter=='last3years' || $date_filter=='daterange' || $date_filter=='all'){
    
        // Date
        $today = date('Y-m-d');
        $yesterday = date("Y-m-d", strtotime("-1 day"));
