					}elseif($date_filter=='30lastdays' || $date_filter=='7lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='daterange'){

						echo '"'.$row_data->day.' '.$months[(int)$row_data->month].'"';

					}else{

						if($row_data->year=='1970'){
							echo '""';
						}elseif($row_data->year=='0'){
							echo '""';
						}else{
							echo '"'.$months[(int)$row_data->month].' '.$row_data->year.'"';
						}

					}
					
					
					if($len2==$no_year){echo'';}else{echo',';} // add koma
                    $no_year++;
				}
			echo '],
			"dataGraphicSuccess": [';
				foreach ($data_graphic as $row_data) {
					$ada = false;
					foreach ($data_graphic_success as $row_data2) {

						if($date_filter=='yesterday' || $date_filter=='today'){
							
							if($row_data->hour==$row_data2->hour){
								echo $row_data2->total;
								$ada = true;
							}

						}elseif($date_filter=='30lastdays' || $date_filter=='7lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='daterange'){
							if($row_data->day==$row_data2->day){
								echo $row_data2->total;
								$ada = true;
							}
						}else{
							if($row_data->month==$row_data2->month && $row_data->year==$row_data2->year){
								echo $row_data2->total;
								$ada = true;
							}
						}
						
					}
					if($ada==false){
						echo 0;
					}
					
					if($len2==$no_month){echo'';}else{echo',';} // add koma
                    $no_month++;
				}
			echo '],
			"dataGraphicWaiting": [';
				foreach ($data_graphic as $row_data) {
					$ada = false;
					foreach ($data_graphic_waiting as $row_data2) {

						if($date_filter=='yesterday' || $date_filter=='today'){
							
							if($row_data->hour==$row_data2->hour){
								echo $row_data2->total;
								$ada = true;
							}

						}elseif($date_filter=='30lastdays' || $date_filter=='7lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='daterange'){
							if($row_data->day==$row_data2->day){
								echo $row_data2->total;
