							}
						}else{
							if($row_data->month==$row_data2->month && $row_data->year==$row_data2->year){
								echo $row_data2->total;
								$ada = true;
							}
						}

					}
					if($ada==false){
						echo 0;
					}
					// echo $row_data->total;
					if($len2==$no_total){echo'';}else{echo',';} // add koma
                    $no_total++;
				}
			echo '],
			"data": [';
				

			echo '
			  ]
		}';

		

	wp_die();

}

