function get_aff_stat($type, $id_usernya){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";
    $table_name2 = $wpdb->prefix . "dja_aff_code";
    $table_name3 = $wpdb->prefix . "dja_aff_click";
    $table_name4 = $wpdb->prefix . "dja_aff_submit";

    if($type=='view'){
    	$total_click_and_view = (int) $wpdb->get_var(
		  $wpdb->prepare(
		    "SELECT COUNT(b.id)
		     FROM {$table_name2} a
		     LEFT JOIN {$table_name3} b ON a.id = b.affcode_id
		     WHERE a.user_id = %d",
		    $id_usernya
		  )
		);
		return $total_click_and_view;
    }
    
    if($type=='submit'){
		$total_click_and_submit = (int) $wpdb->get_var(
		  $wpdb->prepare(
		    "SELECT COUNT(b.id)
		     FROM {$table_name2} a
		     LEFT JOIN {$table_name4} b ON a.id = b.affcode_id
		     WHERE a.user_id = %d",
		    $id_usernya
		  )
		);
		return $total_click_and_submit;
	}

	if($type=='paid'){
		$total_click_submit_and_success = (int) $wpdb->get_var(
		  $wpdb->prepare(
		    "SELECT COUNT(b.id)
		     FROM {$table_name2} a
		     LEFT JOIN {$table_name4} b ON a.id = b.affcode_id
		     LEFT JOIN {$table_name} c ON b.donate_id = c.id
		     WHERE a.user_id = %d
	         AND c.status = %d",
		    $id_usernya,
		    1
		  )
		);
		return $total_click_submit_and_success;
	}

}


function get_payment_expired($invoice_id){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";

	$donate = $wpdb->get_results('SELECT * from '.$table_name.' where invoice_id="'.$invoice_id.'" ');

	$pg = $donate[0]->payment_gateway;
	$pc = $donate[0]->payment_code;

	if($pg=='flip'){

		// Virtual Account	All Banks	24 Hours
		// Retail Store	Alfamart	24 Hours
		// Bank Transfer	All Banks	24 Hours

		// QRIS		1 Hour
		// E-Wallet	ShopeePay	1 Hour
		// E-Wallet	OVO	5 minutes
		// E-Wallet	LinkAja	5 minutes
		// E-Wallet	DANA	30 minutes
		// Card Payment	Credit Card	1 Hour

		$payment_date = $donate[0]->created_at;
		
		if($pc=='qris' || $pc=='shopeepay'){
			$time_plus = strtotime('+1 hour',strtotime($payment_date));
			$additional_info = ' (hanya 1 jam)';
		}elseif($pc=='ovo' || $pc=='linkaja'){
			$time_plus = strtotime('+5 minutes',strtotime($payment_date));
			$additional_info = ' (hanya 5 menit)';
		}elseif($pc=='dana'){
			$time_plus = strtotime('+30 minutes',strtotime($payment_date));
			$additional_info = ' (hanya 30 menit)';
		}else{
			$time_plus = strtotime('+24 hour',strtotime($payment_date));
			$additional_info = ' (24 jam)';
		}
	    
	    return date('d',$time_plus).' '.date('M',$time_plus).' '.date('Y',$time_plus).' - '.date('H:i',$time_plus).$additional_info;

	}else{
		$payment_date = $donate[0]->created_at;
	    $time_plus_24 = strtotime('+24 hour',strtotime($payment_date));
	    return date('d',$time_plus_24).' '.date('M',$time_plus_24).' '.date('Y',$time_plus_24).' - '.date('H:i',$time_plus_24).' (24 jam)';
	}

	

}



function get_payment_method($invoice_id){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_donate";
