		CURLOPT_SSL_VERIFYPEER => 0,
		CURLOPT_HTTPHEADER => [
		  "Accept: application/json",
		],
	]);

	$response = curl_exec($curl);
	$err = curl_error($curl);

	curl_close($curl);

	if ($err) {
		echo "cURL Error #:" . $err;
	} else {
		$array = json_decode($response, true);
	}
	
	// print_r($array);
	
	$method = '';
