';
						foreach ( $value->steps as $value2 ) {
							$value2 = str_replace('<b>','*',$value2);
							$value2 = str_replace('</b>','*',$value2);
							$method .= '- '.$value2.'
';
						}

			}
		}else{

		}	
	}else{
	
		$no = 0;
		foreach ($array as $a => $b) {

			
			if($donate[0]->payment_gateway!=''){ // ada code payment gateway
				
				// pakai yang selain general
