function dja_handling_character($text){
	$set_petikdua = str_replace('"', '&#34;', $text);
    $set_petiksatu = str_replace("'", "&#39;", $set_petikdua);
    $set_garismiring = str_replace("\\", "", $set_petiksatu);
    $set_enter = trim(preg_replace('/\s\s+/', ' ', $set_garismiring));
    $set_enter = wp_strip_all_tags($set_enter);
	return $set_enter;
}


function dja_get_provinsi(){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_users";
    $table_name2 = $wpdb->prefix . "dja_settings";
    $table_name3 = $wpdb->prefix . "dja_wilayah_malaysia";

    $user_id = $_POST['datanya'][0];
  	$profile = $wpdb->get_results("SELECT * FROM $table_name where user_id='$user_id' ")[0];

    // Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name2.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $lang = get_data_lang($currency);

    if($currency=='MYR'){

    	$data_provinsi = '<option value="" data-idprovinsi="">Pilih Negeri</option>';

    	$wilayah_malaysia = $wpdb->get_results('SELECT * from '.$table_name3.' ORDER BY id ASC');
	    // negeri > bandar > daerah
	    foreach ($wilayah_malaysia as $value) { 
	        if($profile->user_provinsi==$value->negeri){
                $data_provinsi .= '<option value="'.$value->negeri.'" data-idprovinsi="'.$value->id.'" selected>'.$value->negeri.'</option>';
            }else{
                $data_provinsi .= '<option value="'.$value->negeri.'" data-idprovinsi="'.$value->id.'">'.$value->negeri.'</option>';
            }
	    }

    }else{

	    $curl = curl_init();
	    $endpoint = "https://wilayah.id/api/provinces.json";

		curl_setopt_array($curl, [
		    CURLOPT_URL => $endpoint,
		    CURLOPT_RETURNTRANSFER => true,
		    CURLOPT_FOLLOWLOCATION => true,
		    CURLOPT_CONNECTTIMEOUT => 10,
		    CURLOPT_TIMEOUT => 15,
		    CURLOPT_HTTPHEADER => ['Accept: application/json'],
		    CURLOPT_SSL_VERIFYHOST => 2,
		    CURLOPT_SSL_VERIFYPEER => true,
		]);

		$response = curl_exec($curl);
		$err      = curl_error($curl);
		$httpcode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
		curl_close($curl);

		$data_provinsi = '<option value="" data-idprovinsi="">Pilih Provinsi</option>';

		if ($err) {
		    echo "cURL Error: " . $err;
		} elseif ($httpcode < 200 || $httpcode >= 300) {
		    echo "HTTP Error: Status {$httpcode}";
		} else {
		    $array = json_decode($response, true);

		    if (json_last_error() !== JSON_ERROR_NONE) {
		        echo "JSON Error: " . json_last_error_msg();
		    } else {
		        // API wilayah.id menaruh daftar provinsi di 'data'
		        $data = isset($array['data']) && is_array($array['data']) ? $array['data'] : [];

		        // Ambil preferensi user (jika ada)
		        $userProvId   = isset($profile->user_provinsi_id) ? (string)$profile->user_provinsi_id : '';
		        $userProvName = isset($profile->user_provinsi_name) ? (string)$profile->user_provinsi_name : '';

		        foreach ($data as $d) {
		            // Normalisasi field dari API wilayah.id
		            $code = isset($d['code']) ? (string)$d['code'] : '';
		            $name = isset($d['name']) ? (string)$d['name'] : '';

		            // Tentukan selected:
		            // 1) cocokkan berdasarkan code (disarankan simpan code)
		            // 2) fallback: cocokkan berdasarkan nama jika Anda menyimpan nama
		            $selected = '';
		            if ($userProvId !== '' && $userProvId === $code) {
		                $selected = ' selected';
		            } elseif ($userProvId === '' && $userProvName !== '' && strcasecmp($userProvName, $name) === 0) {
		                $selected = ' selected';
		            }

		            // value = nama, data-idprovinsi = code (seperti pola lama Anda)
		            $data_provinsi .= '<option value="' . htmlspecialchars($name, ENT_QUOTES, 'UTF-8') . '" data-idprovinsi="' . htmlspecialchars($code, ENT_QUOTES, 'UTF-8') . '"' . $selected . '>' . htmlspecialchars($name, ENT_QUOTES, 'UTF-8') . '</option>';
		        }
		    }
		}


    }
    
    echo $data_provinsi;

    wp_die();

}

add_action( 'wp_ajax_dja_get_provinsi', 'dja_get_provinsi' );
add_action( 'wp_ajax_nopriv_dja_get_provinsi', 'dja_get_provinsi' );  



function dja_get_kabkota(){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_users";
    $table_name2 = $wpdb->prefix . "dja_settings";
    $table_name3 = $wpdb->prefix . "dja_wilayah_malaysia";

    $user_id = $_POST['datanya'][0];
    $id_provinsi = $_POST['datanya'][1];

  	$profile = $wpdb->get_results("SELECT * FROM $table_name where user_id='$user_id' ")[0];

  	// Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name2.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $lang = get_data_lang($currency);

    if($currency=='MYR'){

    	$data_kabkota = '<option value="" data-idkabkota="">Pilih Bandar</option>';

    	$wilayah_malaysia = $wpdb->get_results('SELECT * from '.$table_name3.' where id="'.$id_provinsi.'" ORDER BY id ASC');
	    // negeri > bandar > daerah
	    foreach ($wilayah_malaysia as $value) { 
	        if($profile->user_kabkota==$value->negeri){
                $data_kabkota .= '<option value="'.$value->bandar.'" data-idkabkota="'.$value->id.'" selected>'.$value->bandar.'</option>';
            }else{
                $data_kabkota .= '<option value="'.$value->bandar.'" data-idkabkota="'.$value->id.'">'.$value->bandar.'</option>';
            }
	    }

    }else{

		if ($id_provinsi === '0' || $id_provinsi === 0 || $id_provinsi === '' ) {
		    $id_provinsi = isset($profile->user_provinsi_id) ? (string)$profile->user_provinsi_id : '';
		}
		if ($profile->user_provinsi_id === null && !empty($id_provinsi)) {
		    $id_provinsi = (string)$id_provinsi;
		}

		$endpoint = "https://wilayah.id/api/regencies/{$id_provinsi}.json";

		$curl = curl_init();
		curl_setopt_array($curl, [
		    CURLOPT_URL => $endpoint,
		    CURLOPT_RETURNTRANSFER => true,
		    CURLOPT_FOLLOWLOCATION => true,
		    CURLOPT_CONNECTTIMEOUT => 10,
		    CURLOPT_TIMEOUT => 15,
		    CURLOPT_HTTPHEADER => ['Accept: application/json'],
		    // Di produksi: tetap true/2 agar aman
		    CURLOPT_SSL_VERIFYHOST => 2,
		    CURLOPT_SSL_VERIFYPEER => true,
		]);

		$response = curl_exec($curl);
		$err      = curl_error($curl);
		$httpcode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
		curl_close($curl);

		$data_kabkota = '<option value="" data-idkabkota="">Pilih Kab. Kota</option>';

		if ($err) {
		    echo "cURL Error: " . $err;
		} elseif ($httpcode < 200 || $httpcode >= 300) {
		    echo "HTTP Error: Status {$httpcode}";
		} else {
		    $array = json_decode($response, true);
		    if (json_last_error() !== JSON_ERROR_NONE) {
		        echo "JSON Error: " . json_last_error_msg();
		    } else {
		        // Struktur wilayah.id: ['data' => [ ['code'=>'31.71','name'=>'Kota ...'], ... ]]
		        $rows = isset($array['data']) && is_array($array['data']) ? $array['data'] : [];

		        // Nilai yang Anda simpan untuk kab/kota (id/code &/atau name)
		        $userKabId   = isset($profile->user_kabkota_id) ? (string)$profile->user_kabkota_id : '';
		        $userKabName = isset($profile->user_kabkota_name) ? (string)$profile->user_kabkota_name : '';

		        foreach ($rows as $r) {
		            $code = isset($r['code']) ? (string)$r['code'] : '';
		            $name = isset($r['name']) ? (string)$r['name'] : '';

		            // API wilayah.id sudah memberi "Kabupaten ..." atau "Kota ..."
		            // Jika Anda ingin label pendek "Kab. " / "Kota ", konversi di bawah:
		            $label = $name;
		            if (stripos($name, 'Kabupaten ') === 0) {
		                $label = 'Kab. ' . substr($name, 10); // buang "Kabupaten "
		            } elseif (stripos($name, 'Kota ') === 0) {
		                $label = 'Kota ' . substr($name, 5);  // tetap "Kota ..."
		            }

		            // Tentukan selected:
		            $selected = '';
		            if ($userKabId !== '' && $userKabId === $code) {
		                $selected = ' selected';
		            } elseif ($userKabId === '' && $userKabName !== '' && strcasecmp($userKabName, $name) === 0) {
		                $selected = ' selected';
		            }

		            // value = label yang ditampilkan, data-idkabkota = code (mis. "31.71")
		            $data_kabkota .= '<option value="' .
		                htmlspecialchars($label, ENT_QUOTES, 'UTF-8') .
		                '" data-idkabkota="' .
		                htmlspecialchars($code, ENT_QUOTES, 'UTF-8') .
		                '"' . $selected . '>' .
		                htmlspecialchars($label, ENT_QUOTES, 'UTF-8') .
		                '</option>';
		        }
		    }
		}
	}
	

    echo $data_kabkota;
    wp_die();

}
add_action( 'wp_ajax_dja_get_kabkota', 'dja_get_kabkota' );
add_action( 'wp_ajax_nopriv_dja_get_kabkota', 'dja_get_kabkota' );  


function dja_get_kecamatan(){

	global $wpdb;
    $table_name = $wpdb->prefix . "dja_users";
    $table_name2 = $wpdb->prefix . "dja_settings";
    $table_name3 = $wpdb->prefix . "dja_wilayah_malaysia";

    $user_id = $_POST['datanya'][0];
    $id_kabkota = $_POST['datanya'][1];

  	$profile = $wpdb->get_results("SELECT * FROM $table_name where user_id='$user_id' ")[0];

  	// Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name2.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $lang = get_data_lang($currency);

    if($currency=='MYR'){

    	$data_kecamatan = '<option value="" data-idprovinsi="">Pilih Daerah</option>';

    	$wilayah_malaysia = $wpdb->get_results('SELECT * from '.$table_name3.' where id="'.$id_kabkota.'" ORDER BY id ASC');
	    // negeri > bandar > daerah
	    foreach ($wilayah_malaysia as $value) { 
	        $myArray = explode(',', $value->daerah);

	        foreach ($myArray as $key => $val) {
	           if($profile->user_kabkota==$value->negeri){
	                $data_kecamatan .= '<option value="'.$val.'" data-idkecamatan="'.$value->id.'" selected>'.$val.'</option>';
	            }else{
	                $data_kecamatan .= '<option value="'.$val.'" data-idkecamatan="'.$value->id.'">'.$val.'</option>';
	            }
	        }
	    }

    }else{


	    if ($id_kabkota === '0' || $id_kabkota === 0 || $id_kabkota === '') {
		    $id_kabkota = isset($profile->user_kabkota_id) ? (string)$profile->user_kabkota_id : '';
		}
		if ($profile->user_kabkota_id === null && !empty($id_kabkota)) {
		    $id_kabkota = (string)$id_kabkota;
		}

		$endpoint = "https://wilayah.id/api/districts/{$id_kabkota}.json";

		$curl = curl_init();
		curl_setopt_array($curl, [
		    CURLOPT_URL => $endpoint,
		    CURLOPT_RETURNTRANSFER => true,
		    CURLOPT_FOLLOWLOCATION => true,
		    CURLOPT_CONNECTTIMEOUT => 10,
		    CURLOPT_TIMEOUT => 15,
		    CURLOPT_HTTPHEADER => ['Accept: application/json'],
		    // Produksi: verifikasi SSL aktif
		    CURLOPT_SSL_VERIFYHOST => 2,
		    CURLOPT_SSL_VERIFYPEER => true,
		]);

		$response = curl_exec($curl);
		$err      = curl_error($curl);
		$httpcode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
		curl_close($curl);

		$data_kecamatan = '<option value="" data-idkecamatan="">Pilih Kecamatan</option>';

		if ($err) {
		    echo "cURL Error: " . $err;
		} elseif ($httpcode < 200 || $httpcode >= 300) {
		    echo "HTTP Error: Status {$httpcode}";
		} else {
		    $array = json_decode($response, true);
		    if (json_last_error() !== JSON_ERROR_NONE) {
		        echo "JSON Error: " . json_last_error_msg();
		    } else {
		        // wilayah.id -> ['data' => [ ['code'=>'31.74.06','name'=>'Cilandak'], ... ]]
		        $rows = isset($array['data']) && is_array($array['data']) ? $array['data'] : [];

		        // Nilai yang Anda simpan (id/code &/atau name)
		        $userKecId   = isset($profile->user_kecamatan_id) ? (string)$profile->user_kecamatan_id : '';
		        $userKecName = isset($profile->user_kecamatan_name) ? (string)$profile->user_kecamatan_name : '';

		        foreach ($rows as $r) {
		            $code = isset($r['code']) ? (string)$r['code'] : '';
		            $name = isset($r['name']) ? (string)$r['name'] : '';

		            // Selected by code; fallback by name jika yang disimpan nama
		            $selected = '';
		            if ($userKecId !== '' && $userKecId === $code) {
		                $selected = ' selected';
		            } elseif ($userKecId === '' && $userKecName !== '' && strcasecmp($userKecName, $name) === 0) {
		                $selected = ' selected';
		            }

		            // value = nama kecamatan, data-idkecamatan = code (mis. "31.74.06")
		            $data_kecamatan .= '<option value="' .
		                htmlspecialchars($name, ENT_QUOTES, 'UTF-8') .
		                '" data-idkecamatan="' .
		                htmlspecialchars($code, ENT_QUOTES, 'UTF-8') .
		                '"' . $selected . '>' .
		                htmlspecialchars($name, ENT_QUOTES, 'UTF-8') .
		                '</option>';
		        }
		    }
		}


	}


    echo $data_kecamatan;
    wp_die();

}
